# device.reset: each scope removes what it names, and only the classes that may ask can (#446)
TS=sim/tests/test_device_reset.py
mutate reset_preauth_denies_cable src/helpers/iface/DeployAuth.cpp '!plain_read && op.priv != PRIV_REBOOT && op.priv != PRIV_DESTRUCTIVE &&' '!plain_read && op.priv != PRIV_REBOOT &&' "$TS::test_enrolled_the_cable_keeps_it_and_a_signature_never_gets_it[companion_standalone]"
mutate reset_enrolled_not_told_companion examples/companion_radio/MeconIface.cpp '  ctx.enrolled = (cls == Cli::C_READ || cls == Cli::C_REBOOT || cls == Cli::C_DESTRUCTIVE) && self->_auth.enrolled();' '  ctx.enrolled = (cls == Cli::C_READ || cls == Cli::C_REBOOT) && self->_auth.enrolled();' "$TS::test_paired_ble_may_on_a_standalone_device_and_not_once_enrolled"
mutate reset_radio_keeps_freq_companion examples/companion_radio/MyMesh.cpp '      _prefs.freq = LORA_FREQ;' '' "$TS::test_radio_goes_back_to_the_builds_default_and_nothing_else[companion_standalone]"
mutate reset_radio_keeps_sf_repeater examples/simple_repeater/MyMesh.cpp '      _prefs.sf = LORA_SF;' '' "$TS::test_radio_goes_back_to_the_builds_default_and_nothing_else[repeater]"
mutate reset_network_keeps_wifi_repeater examples/simple_repeater/MyMesh.cpp '      for (uint8_t i = 0; i < WifiProfiles::COUNT; i++) _prefs.wifi_profiles.clear(i);' '' "$TS::test_network_removes_every_stored_profile_and_keeps_the_rest[repeater_wifi]"
mutate reset_network_keeps_mqtt_companion examples/companion_radio/MyMesh.cpp '      for (uint8_t i = 0; i < MqttProfiles::COUNT; i++) _prefs.mqtt_profiles.clear(i);' '' "$TS::test_network_removes_every_stored_profile_and_keeps_the_rest[companion_standalone]"
mutate reset_contacts_kept examples/companion_radio/MyMesh.cpp '      const bool ok = cs.clearAll();' '      const bool ok = true;' "$TS::test_contacts_removes_the_table_and_keeps_the_channels"
mutate reset_channels_public_not_restored examples/companion_radio/MyMesh.cpp '      setChannel(0, _public_channel);   // as boot made it, before the stored channels were loaded' '' "$TS::test_channels_keeps_only_the_public_one_and_the_contacts"
mutate reset_reboot_drops_lazy_contacts examples/companion_radio/MeconIface.cpp '    _mesh->saveDirtyContacts();   // as the native CMD_REBOOT does: a contact change still waiting for its lazy save' '' "$TS::test_a_contact_added_just_before_a_reboot_is_kept"
mutate reset_factory_writes_back_contacts examples/companion_radio/MyMesh.cpp '      dirty_contacts_expiry = 0;   // nothing written back into the erased files before the reboot' '' "$TS::test_factory_is_the_native_reset[companion_standalone]"
mutate reset_bonds_unnamed src/helpers/iface/ResetOps.cpp '  if (s == RS_BONDS) { c.error = "not-built"; return ST_FAILED; }   // each BLE stack'"'"'s bond store, with a board check each' '' "$TS::test_scopes_that_are_not_this_operations_say_where_to_go[repeater]"
